import type { LayoutCode } from "./housingMarket.js";
import type { MlitBuyAgeBand } from "./buyMarket.js";

export interface MlitBuyAgeBandSnapshot {
  medianSqmPriceYen: number;
  sampleCount: number;
}

/** 同分桶內「改装済み」與「未改装」的實際成交㎡單價對照。 */
export interface MlitRenovationPremium {
  renovatedSqmPriceYen: number;
  unrenovatedSqmPriceYen: number;
  renovatedSampleCount: number;
  unrenovatedSampleCount: number;
}

/** 同分桶內 SRC 與 RC 的實際成交㎡單價對照（SRC 為塔樓的近似代理）。 */
export interface MlitStructurePremium {
  srcSqmPriceYen: number;
  rcSqmPriceYen: number;
  srcSampleCount: number;
  rcSampleCount: number;
}

export interface MlitBuySnapshotRow {
  region: string;
  district: string;
  layout: LayoutCode;
  medianTradePriceYen: number;
  medianSqmPriceYen: number;
  medianAreaSqm: number;
  ageBands: Partial<Record<MlitBuyAgeBand, MlitBuyAgeBandSnapshot>>;
  buildingYearSampleCount: number;
  structureCounts: Record<string, number>;
  sampleCount: number;
  windowQuarters: 4 | 8 | 12 | 16;
  periodStart: string;
  periodEnd: string;
  sourceUrl: string;
}

